export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/longnet; mkdir -p $D && cd $D || exit 1
cat > /tmp/ln.b64 <<'B64EOF'

B64EOF
rm -rf ./*; base64 -d /tmp/ln.b64 > /tmp/ln.zip && unzip -oq /tmp/ln.zip -d .
for t in s_near s_far; do
  /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source ./$t.tcl > $t.log 2>&1
  grep -q "DONE_$t" $t.log && echo "OK $t" || { echo "FAIL $t"; grep ERROR $t.log | head -3; }
done
tar czf /tmp/longnet_out.tgz *.bit *.log 2>/dev/null; echo TAR_DONE